// Original Canvas2D triangle renderer. A visibly simplified, navigable CPU fallback.
// Uses Three.js transforms and perspective math; no GPU, server or screenshots.
import * as THREE from '../vendor/three.module.js';
export class SoftwareRenderer {
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d',{alpha:false});if(!this.ctx)throw Error('Canvas2D unavailable');this.isSoftware=true;this.pixelRatio=1;this.shadowMap={};this.info={render:{calls:0,triangles:0}};this.cache=new Map();this.simpleSphere=new THREE.SphereGeometry(1,6,4);this.simpleCylinder=new THREE.CylinderGeometry(1,1,1,6);this.sunDirection=new THREE.Vector3(-.5,.8,.35).normalize();this.colorCache=new Map();}
 setPixelRatio(){this.pixelRatio=1;}
 setSize(w,h){this.w=Math.round(w);this.h=Math.round(h);this.canvas.width=this.w;this.canvas.height=this.h;}
 geometry(geo){if(geo.type==='SphereGeometry')geo=this.simpleSphere;if(geo.type==='CylinderGeometry'&&geo.parameters.radiusTop===geo.parameters.radiusBottom)geo=this.simpleCylinder;if(this.cache.has(geo.uuid))return this.cache.get(geo.uuid);const pos=geo.attributes.position.array,index=geo.index?.array,faces=[];for(let i=0;i<(index?index.length:pos.length/3);i+=3){let ids=index?[index[i],index[i+1],index[i+2]]:[i,i+1,i+2];const pts=ids.map(id=>[pos[id*3],pos[id*3+1],pos[id*3+2]]);let a=new THREE.Vector3(...pts[0]),b=new THREE.Vector3(...pts[1]),c=new THREE.Vector3(...pts[2]),n=b.clone().sub(a).cross(c.clone().sub(a)).normalize();faces.push({ids,normal:n});}const result={pos,faces};this.cache.set(geo.uuid,result);return result;}
 render(scene,camera){if(!this.w)return;scene.updateMatrixWorld();camera.updateMatrixWorld();camera.matrixWorldInverse.copy(camera.matrixWorld).invert();const vp=new THREE.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse),ctx=this.ctx,w=this.w,h=this.h;const bg=scene.background.clone(),night=bg.r<.04;let gradient=ctx.createLinearGradient(0,0,0,h);gradient.addColorStop(0,bg.getStyle());gradient.addColorStop(1,bg.clone().lerp(new THREE.Color('#e3d9bc'),night?.1:.4).getStyle());ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);const faces=[];let calls=0;const matrix=new THREE.Matrix4(),instance=new THREE.Matrix4();
 const project=(x,y,z,m)=>{const e=m.elements,a=e[0]*x+e[4]*y+e[8]*z+e[12],b=e[1]*x+e[5]*y+e[9]*z+e[13],c=e[2]*x+e[6]*y+e[10]*z+e[14],d=e[3]*x+e[7]*y+e[11]*z+e[15];return [(a/d*.5+.5)*w,(-b/d*.5+.5)*h,d,c/d];};
 const submit=(object,world)=>{let mat=Array.isArray(object.material)?object.material[0]:object.material;if(!mat||mat.opacity<.2)return;let data=this.geometry(object.geometry);matrix.multiplyMatrices(vp,world);const position=data.pos,projected=[];for(let i=0;i<position.length;i+=3)projected.push(project(position[i],position[i+1],position[i+2],matrix));let base=mat.map&&object.geometry.type==='PlaneGeometry'?new THREE.Color('#b7ac98'):mat.color||new THREE.Color('#bbbbaa');const scale=new THREE.Vector3().setFromMatrixScale(world);if(Math.max(scale.x,scale.y,scale.z)<.2)return;
 for(const f of data.faces){let a=projected[f.ids[0]],b=projected[f.ids[1]],c=projected[f.ids[2]];if(a[2]<.18||b[2]<.18||c[2]<.18)continue;if((a[0]<-5&&b[0]<-5&&c[0]<-5)||(a[0]>w+5&&b[0]>w+5&&c[0]>w+5)||(a[1]<-5&&b[1]<-5&&c[1]<-5)||(a[1]>h+5&&b[1]>h+5&&c[1]>h+5))continue;const area=(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);if(mat.side!==THREE.DoubleSide&&area>=0)continue;if(Math.abs(area)<.3)continue;let depth=(a[2]+b[2]+c[2])/3;const normal=f.normal.clone().transformDirection(world);let shade=night?.22+.14*Math.max(0,normal.dot(this.sunDirection)):.65+.4*Math.max(0,normal.dot(this.sunDirection));if(scene.fog.far<150)shade=.78;shade=Math.round(shade*12)/12;let fog=clamp((depth-scene.fog.near)/(scene.fog.far-scene.fog.near),0,.96);fog=Math.round(fog*12)/12;const key=base.getHexString()+shade+fog+bg.getHexString();let color=this.colorCache.get(key);if(!color){color=base.clone().multiplyScalar(shade).lerp(bg,fog).getStyle();this.colorCache.set(key,color);}faces.push({a,b,c,depth,color,ground:object.geometry.type==='PlaneGeometry',opacity:mat.transparent?mat.opacity:1});}
 calls++;};
 scene.traverseVisible(o=>{if(!o.isMesh)return;if(o.isInstancedMesh){for(let i=0;i<o.count;i++){o.getMatrixAt(i,instance);submit(o,new THREE.Matrix4().multiplyMatrices(o.matrixWorld,instance));}}else submit(o,o.matrixWorld);});
 // Floor joints, projected and depth sorted with the buildings and actors.
 const line=(a,b)=>{let pa=project(...a,vp),pb=project(...b,vp);if(pa[2]>.2&&pb[2]>.2)faces.push({ground:true,line:true,a:pa,b:pb,depth:(pa[2]+pb[2])/2});};for(let x=-72;x<=65;x+=7)line([x,.025,-49],[x,.025,49]);for(let z=-49;z<=49;z+=7)line([-72,.025,z],[65,.025,z]);
 faces.sort((a,b)=>(!!a.ground!==!!b.ground)?(a.ground?-1:1):a.ground&&a.line!==b.line?(a.line?1:-1):b.depth-a.depth);for(let f of faces){if(f.line){ctx.globalAlpha=.22;ctx.strokeStyle=night?'#8c998f':'#656b60';ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(f.a[0],f.a[1]);ctx.lineTo(f.b[0],f.b[1]);ctx.stroke();continue;}ctx.globalAlpha=f.opacity;ctx.fillStyle=f.color;ctx.beginPath();ctx.moveTo(f.a[0],f.a[1]);ctx.lineTo(f.b[0],f.b[1]);ctx.lineTo(f.c[0],f.c[1]);ctx.closePath();ctx.fill();}
 ctx.globalAlpha=1;this.info.render.calls=calls;this.info.render.triangles=faces.length;
 // Rain is a demonstrative screen-space effect in CPU mode.
 const rain=scene.children.find(o=>o.isPoints&&o.visible);if(rain){ctx.strokeStyle='#d6e2e877';ctx.lineWidth=.8;ctx.beginPath();let t=performance.now()*.4;for(let i=0;i<110;i++){let x=(i*137.3)%w,y=(i*73.8+t)%h;ctx.moveTo(x,y);ctx.lineTo(x-2,y+13);}ctx.stroke();}
 }
}
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
